$ops=@(
@('API-IAM-01','issueOtp','post','/v1/auth/otp','Identity','A1','FR-IDN-001'),@('API-IAM-02','verifyOtp','post','/v1/auth/otp/verify','Identity','A1','FR-IDN-001'),@('API-ADM-01','createEmployee','post','/v1/employees','Identity','A1','FR-IDN-008'),@('API-VEH-01','registerVehicle','post','/v1/vehicles','Vehicles','A2','FR-VEH-001'),@('API-RTE-01','createRouteVersion','post','/v1/routes','Routes','A2','FR-RTE-002'),@('API-STA-01','queueCheckIn','post','/v1/stations/{stationId}/queue/check-ins','Stations/Queue','A2','FR-STA-001'),@('API-STA-02','queueLeave','post','/v1/queue/{entryId}/leave','Stations/Queue','A2','FR-STA-010'),@('API-LOC-01','recordGpsObservation','post','/v1/location/observations','Location','A2','FR-LOC-001'),@('API-BKG-01','holdSeat','post','/v1/bookings/holds','Booking','A2','FR-BKG-001'),@('API-BKG-02','confirmBooking','post','/v1/bookings/{bookingId}/confirm','Booking','A2','FR-BKG-005'),@('API-BKG-03','cancelBooking','post','/v1/bookings/{bookingId}/cancel','Booking','A2','FR-BKG-009'),@('API-TAX-01','acceptTaxiOffer','post','/v1/taxi/offers/{offerId}/accept','Booking','A2','FR-BKG-013'),@('API-TAX-02','activateStreetQr','post','/v1/taxi/qr/{token}/activate','Booking','A2','FR-BKG-014'),@('API-TAX-03','finishTaxiTrip','post','/v1/taxi/trips/{tripId}/finish','Trips','A2','FR-BKG-016'),@('API-PRC-01','publishPriceVersion','post','/v1/pricing/versions','Pricing','A3','FR-PRC-002'),@('API-WLT-01','walletPayment','post','/v1/wallet/payments','Wallet','A3','FR-WLT-007'),@('API-WLT-02','requestWithdrawal','post','/v1/wallet/withdrawals','Wallet','A3','FR-WLT-008'),@('API-WLT-03','approveWithdrawal','post','/v1/wallet/withdrawals/{withdrawalId}/approve','Wallet','A3','FR-WLT-009'),@('API-COM-01','submitComplaint','post','/v1/complaints','Complaints','A1','FR-COM-001'),@('API-CMP-01','recordComplianceDecision','post','/v1/compliance/cases/{caseId}/decisions','Compliance','A1','FR-CMP-001'),@('API-INV-01','registerEvidence','post','/v1/investigations/{caseId}/evidence','Investigation','A1','FR-INV-002'),@('API-PLT-01','recordEmployeeSignal','post','/v1/platform/employee-signals','Platform Management','A3','FR-PLT-001'),@('API-TSK-01','completeTask','post','/v1/tasks/{taskId}/complete','Tasks','A3','FR-TSK-005'),@('API-NTF-01','listNotifications','get','/v1/notifications','Notifications','A3','FR-NTF-006'),@('API-AUD-01','queryAuditLog','get','/v1/audit/events','Audit','A7','FR-AUD-001'))
$paths=[ordered]@{};foreach($o in $ops){$method=$o[2];$paths[$o[3]]=[ordered]@{};$paths[$o[3]][$method]=[ordered]@{operationId=$o[1];summary=$o[0];tags=@($o[4]);'x-madar-contract-id'=$o[0];'x-madar-owner-domain'=$o[4];'x-madar-owner-agent'=$o[5];'x-madar-srs'=@($o[6]);'x-authorization-scope'='Subject + Action + Resource + Organization Scope + Context';'x-idempotency'=if($method -eq 'post'){'Idempotency-Key required; same key/different request = 409'}else{'Not applicable'};parameters=@(@{name='X-Correlation-ID';in='header';required=$true;schema=@{type='string'}});responses=[ordered]@{'200'=@{description='Success; resourceId/state/version/serverTime/correlationId as applicable';content=@{'application/json'=@{schema=@{'$ref'='#/components/schemas/SuccessEnvelope'}}}};'401'=@{'$ref'='#/components/responses/Unauthorized'};'403'=@{'$ref'='#/components/responses/Forbidden'};'409'=@{'$ref'='#/components/responses/Conflict'};'422'=@{'$ref'='#/components/responses/ValidationError'};'503'=@{'$ref'='#/components/responses/DependencyFailure'}}}}
$spec=[ordered]@{openapi='3.1.0';info=@{title='MADAR V1 Contract Baseline';version='1.0.0-proposed';description='S01 proposed contract baseline. Schemas are not production implementation.'};servers=@(@{url='https://api.example.invalid'});paths=$paths;components=@{schemas=@{SuccessEnvelope=@{type='object';required=@('correlationId');properties=@{resourceId=@{type='string'};state=@{type='string'};version=@{type='integer'};serverTime=@{type='string';format='date-time'};correlationId=@{type='string'}}};ErrorEnvelope=@{type='object';additionalProperties=$false;required=@('code','message','correlationId','retryable');properties=@{code=@{type='string'};message=@{type='string'};correlationId=@{type='string'};retryable=@{type='boolean'};details=@{type='array';items=@{type='object'}}}}};responses=@{Unauthorized=@{description='Authentication required'};Forbidden=@{description='Authorization denied'};Conflict=@{description='State, idempotency, or concurrency conflict'};ValidationError=@{description='Safe validation error'};DependencyFailure=@{description='Critical dependency unavailable'}}}}
$json=$spec|ConvertTo-Json -Depth 30;W (Join-Path $c 'openapi/v1.openapi.json') $json
$eventNames=@('identity.account.verified.v1','queue.entry.checked-in.v1','booking.hold.created.v1','booking.confirmed.v1','taxi.trip.completed.v1','wallet.ledger.posted.v1','withdrawal.requested.v1','complaint.submitted.v1','evidence.registered.v1','task.completed.v1','notification.created.v1')
$envelope=@{ '$schema'='https://json-schema.org/draft/2020-12/schema';title='MADAR Domain Event Envelope';type='object';additionalProperties=$false;required=@('eventId','eventType','schemaVersion','occurredAt','correlationId','aggregate','payload');properties=@{eventId=@{type='string'};eventType=@{type='string';enum=$eventNames};schemaVersion=@{const='1.0.0'};occurredAt=@{type='string';format='date-time'};correlationId=@{type='string'};causationId=@{type='string'};aggregate=@{type='object';required=@('type','id');properties=@{type=@{type='string'};id=@{type='string'}}};payload=@{type='object'}}};W (Join-Path $c 'events/domain-event-envelope.schema.json') ($envelope|ConvertTo-Json -Depth 20)
$err=$spec.components.schemas.ErrorEnvelope;W (Join-Path $c 'schemas/error-envelope.schema.json') (($err+@{'$schema'='https://json-schema.org/draft/2020-12/schema';title='MADAR Error Envelope'})|ConvertTo-Json -Depth 20)
$fixture=@{eventId='evt_01';eventType='booking.confirmed.v1';schemaVersion='1.0.0';occurredAt='2026-11-19T00:00:00Z';correlationId='corr_01';aggregate=@{type='booking';id='bkg_01'};payload=@{bookingId='bkg_01';status='CONFIRMED'}};W (Join-Path $c 'fixtures/valid-booking-confirmed-event.json') ($fixture|ConvertTo-Json -Depth 10);W (Join-Path $c 'fixtures/invalid-event-missing-correlation.json') ((@{eventId='evt_bad';eventType='booking.confirmed.v1';schemaVersion='1.0.0';occurredAt='not-a-date';aggregate=@{type='booking';id='bkg'};payload=@{}})|ConvertTo-Json -Depth 10)
$domainRows=@('Identity|Accounts, sessions, OTP, employee identity|A1|RESTRICTED','Vehicles|Vehicle and driver master data|A2|CONFIDENTIAL','Routes|Route versions, stops and segments|A2|INTERNAL','Stations/Queue|Station authority and ordered queue entries|A2|CONFIDENTIAL','Location|GPS observations and geofence decisions|A2|RESTRICTED','Booking|Seat holds, bookings and taxi dispatch state|A2|CONFIDENTIAL','Trips|Trip operational state and fare snapshot reference|A2|CONFIDENTIAL','Pricing|Versioned tariffs and price snapshots|A3|CONFIDENTIAL','Wallet|Append-only balanced financial ledger|A3|RESTRICTED','Complaints|Complaint cases and appeal links|A1|RESTRICTED','Compliance|Compliance cases and sanctions|A1|RESTRICTED','Investigation|Evidence/custody and investigation cases|A1|RESTRICTED','Platform Management|Employee activity indicators|A3|RESTRICTED','Tasks|Assignments and completion state|A3|INTERNAL','Notifications|Delivery records and read state|A3|CONFIDENTIAL','Audit|Sensitive action records|A7|RESTRICTED')
$dt=$domainRows|ForEach-Object{$x=$_-split '\|';"| $($x[0]) | $($x[1]) | $($x[2]) | $($x[3]) |"}
W (Join-Path $a 'domain-catalog.md') ("# كتالوج المجالات`n`n| المجال | المسؤولية | المالك | التصنيف |`n|---|---|---|---|`n"+($dt -join "`n")+"`n`nالملكية منطقية؛ لا تثبت جداول أو ORM قبل S03. المجالات السبعة المركزية هي Location وBooking وCompliance وComplaints وInvestigation وPlatform Management وWallet. التطبيقات تستهلك عقودًا عامة فقط.")
W (Join-Path $a 'context-map.md') "# خريطة السياق`n`nالحدود: التطبيقات ← API versioned contracts ← المجالات المالكة. التكامل بين المجالات يتم بعقد API أو event outbox فقط. لا توجد كتابة مباشرة عبر schema. Location يملك GPS؛ Booking يملك الحجز؛ Wallet يملك دفتر الحقيقة المالي؛ Queue يملك الترتيب؛ Vehicles يملك بيانات المركبة الأساسية."
$cmd=$ops|Where-Object{$_[2]-eq'post'}|ForEach-Object{"| CMD-$($_[1]) | $($_[1]) | $($_[4]) | API principal within authorized scope | Idempotency-Key; state/version checks | $($_[6]) |"};W (Join-Path $a 'commands-catalog.md') ("# كتالوج الأوامر`n`nكل أمر يحتاج مصادقة وصلاحية ونطاقاً تنظيمياً وسجل تدقيق، ومعاملة ذرية/Outbox حيث ينتج حدثًا. الحدود المالية والحجز تستخدم قيد DB والتزامن في S03.`n`n| Command ID | العملية | المجال | الفاعل | الحماية | المرجع |`n|---|---|---|---|---|---|`n"+($cmd-join"`n"))
$qry=$ops|Where-Object{$_[2]-eq'get'}|ForEach-Object{"| QRY-$($_[1]) | $($_[1]) | $($_[4]) | فاعل مخول بالنطاق | pagination/sorting allowlist | $($_[6]) |"};W (Join-Path $a 'queries-catalog.md') ("# كتالوج الاستعلامات`n`nالاستعلامات لا تعدل الحالة، وتطبق scope وpagination وsorting آمنًا؛ لا تعرض حقولًا RESTRICTED دون غرض وصلاحية.`n`n| Query ID | العملية | المجال | الفاعل | القيود | المرجع |`n|---|---|---|---|---|---|`n"+($qry-join"`n"))
$ev=$eventNames|ForEach-Object{"| EVT-$($_.Replace('.','-')) | $_ | المجال المنتج بحسب البادئة | مستهلكون مخولون عبر contract | at-least-once; dedupe eventId |"};W (Join-Path $a 'events-catalog.md') ("# كتالوج الأحداث`n`nجميع الأحداث تحمل eventId/correlationId/causationId عند توفره ووقت الحدوث وaggregate. التسليم at-least-once عبر transactional outbox؛ المستهلك يمنع التكرار ولا تحتوي الحمولة أسراراً أو OTP/tokens.`n`n| ID | الحدث | المنتج | المستهلكون | الضمان |`n|---|---|---|---|---|`n"+($ev-join"`n"))
W (Join-Path $a 'integration-map.md') "# خريطة التكامل`n`nProvider boundaries: Identity للـOTP adapter، Wallet لمزود الدفع، Location للخرائط/GPS، Compliance/Investigation للجهات الحكومية. OPEN-06 وOPEN-08 تمنع التفعيل الحقيقي؛ تستخدم adapters/mocks فقط. لا exactly-once؛ outbox + idempotent consumer."
W (Join-Path $a 'data-ownership.md') "# ملكية البيانات`n`n| الكيان | المالك | الكاتب المخول | نمط الاتساق |`n|---|---|---|---|`n| GPS Observation | Location | Location workflow | quality/timestamp + audit |`n| Booking/Hold | Booking | Booking workflow | atomic capacity/idempotency |`n| Queue Entry | Stations/Queue | authorized station workflow | ordered state/version |`n| Ledger/Balance | Wallet | Wallet workflow | append-only double entry |`n| Vehicle | Vehicles | authorized vehicle workflow | history/audit |`n| Evidence | Investigation | assigned investigator | hash/custody/access audit |`n`nالقارئ يستخدم عقدًا عامًا؛ لا ORM مشترك ولا repository داخلي." 
W (Join-Path $a 'schema-boundaries.md') "# حدود الـSchema`n`nSchema منطقي لكل مجال، بلا cross-schema writes أو استيراد repositories/entities داخلية. العقود العامة وports/events فقط مسموحة. اسم schema الفعلي مؤجل لـS03؛ A7 يملك migrations." 
W (Join-Path $a 'transaction-boundaries.md') "# حدود المعاملات`n`nBooking hold/confirm، queue check-in، ledger posting، withdrawal request/approval، taxi finish تتطلب معاملة محلية ذرية + idempotency record + outbox. السعة والرصيد: unique constraints/row locks أو optimistic version وفق العملية. لا transaction موزعة؛ recovery/compensation عبر workflow موثق." 
W (Join-Path $a 'consistency-model.md') "# نموذج الاتساق`n`nمصدر الحقيقة قوي الاتساق داخل المجال. القراءات عبر الأحداث قد تكون eventually consistent ولا تصبح مصدر الحقيقة للسعة أو المال. `409` لتعارض الحالة/السعة، و`503` لتعطل تابع حرج؛ لا نجاح وهمي." 
W (Join-Path $a 'api-contracts.md') "# عقود API`n`nالعقد الميكانيكي: `packages/contracts/openapi/v1.openapi.json`، OpenAPI 3.1، version `1.0.0-proposed`. كل عملية لها Contract ID، مالك، Agent، مرجع SRS، scope، correlation، وأخطاء آمنة. POST يتطلب `Idempotency-Key`؛ لا تدعي المخططات وجود implementation." 
W (Join-Path $a 'error-taxonomy.md') "# تصنيف الأخطاء`n`nEnvelope: `code`, `message`, `correlationId`, `retryable`, `details` الآمنة. `VALIDATION_ERROR`=422، `AUTHENTICATION_REQUIRED`=401، `FORBIDDEN`=403، `NOT_FOUND`=404، `STATE_CONFLICT`/`CONCURRENCY_CONFLICT`/`IDEMPOTENCY_CONFLICT`=409، `RATE_LIMITED`=429، `DEPENDENCY_UNAVAILABLE`=503، `INTERNAL_ERROR`=500. لا stack traces أو SQL أو OTP أو tokens أو secrets؛ الأخطاء الحساسة تدقق." 
W (Join-Path $a 'idempotency-policy.md') "# سياسة Idempotency`n`nالنطاق هو actor+operation+Idempotency-Key، مع fingerprint للطلب. نفس المفتاح/نفس payload يعيد النتيجة المحفوظة؛ نفس المفتاح/payload مختلف=409؛ in-progress يمنع الأثر المكرر؛ failure يسجل outcome قابلًا للمراجعة. التخزين عند المجال المالك، والاحتفاظ configurable بلا مدة مخترعة. تنطبق على booking، queue، trip، ledger/payment/refund، withdrawal، وconsumer events." 
W (Join-Path $a 'concurrency-invariants.md') "# ثوابت التزامن`n`nلا Overbooking، لا Double Spend، لا queue entry مزدوج، لا QR/finish/payment callback مكرر. الحماية: transaction محلية، unique constraints، state preconditions/expectedVersion، row locks عند السعة/الرصيد، ledger balance invariants، and idempotency records. اختبارات DB الحقيقية مؤجلة لـS03 وما بعده." 
W (Join-Path $a 'versioning-policy.md') "# سياسة الإصدارات`n`nAPI تحت `/v1`; إضافة حقل اختياري أو operation جديدة non-breaking. إزالة operation/required field أو تغيير type/enum بصورة تقيد مستهلكًا breaking ويستلزم major version/مسار توافق. الأحداث تحمل suffix `.v1` وschemaVersion. لا حذف قبل deprecation وإثبات توافق." 
W (Join-Path $a 'compatibility-policy.md') "# سياسة التوافق`n`nالفحص يقارن baseline مع candidate ويمنع حذف operationId أو تغيير required/type أو response/error contract دون version جديد. فحص S01 محلي فقط؛ CI integration مؤجل S02. mutation السلبي يتم في الذاكرة ثم تؤكد إعادة baseline دون تعديل ملف العقد." 
W (Join-Path $a 'trust-boundaries.md') "# حدود الثقة`n`nالعميل غير موثوق؛ API boundary يفرض authz. Provider callbacks غير موثوقة حتى تحقق signature/replay policy. التطبيق ← API ← domain ← outbox/consumer حدود منفصلة. GPS العميل إشارة لا دليل قاطع. evidence وwallet وidentity مناطق RESTRICTED." 
W (Join-Path $a 'data-classification.md') "# تصنيف البيانات`n`nPUBLIC: لا توجد بيانات تشغيلية افتراضية. INTERNAL: routes/tasks metadata. CONFIDENTIAL: booking/vehicle/notification data. RESTRICTED: identity documents, OTP/session material, GPS, wallet ledger, complaints, evidence, audit. RESTRICTED لا يطبع في logs ولا fixtures؛ export يحتاج scope/audit. retention=OPEN-07، ولا مدة أو موافقة قانونية مفترضة." 
W (Join-Path $a 'security-controls.md') "# الضوابط الأمنية`n`nOTP rate limiting/non-enumeration، session/device control، server-side authorization، scoped access، idempotency/replay protection، parameterized storage، secret manager، encryption in transit/at rest subject to deployment, immutable audit trail، evidence hash/custody، safe errors، outbox dedupe، least privilege. التحقق التشغيلي الكامل مؤجل للتنفيذ." 
W (Join-Path $a 'security-test-plan.md') "# خطة اختبار الأمن`n`nاختبر لاحقًا: OTP brute force/enumeration, IDOR, scope escape, GPS spoof/remote queue, overbooking, QR replay, fare tampering, double spend, callback replay, evidence leakage/tampering, audit tampering. S01 يتحقق من contract declarations والfixtures فقط؛ لا يثبت runtime security." 
W (Join-Path $a 'dependency-rules.md') "# قواعد الاعتماد`n`nممنوع: domain→internal domain service/repository/ORM entity، frontend→backend internals، shared utility containing domain logic. مسموح: versioned contracts، public ports، events، shared technical utilities. اختبار S01 مصطنع/تمثيلي لأن monorepo غير موجود؛ S02 يدمجه في lint/CI." 
$reg=$ops|ForEach-Object{"| $($_[0]) | $($_[1]) | API | $($_[4]) | A$($_[5].Substring(1)) | $($_[6]) | openapi/v1.openapi.json | 1.0.0-proposed | SPECIFIED |"};W (Join-Path $a 'contracts-registry.md') ("# سجل العقود`n`n| Contract ID | Name | Type | Provider | Agent | SRS | File | Version | Status |`n|---|---|---|---|---|---|---|---|---|`n"+($reg-join"`n")+"`n`nEvents use `events/domain-event-envelope.schema.json`; provider is the domain named in event type; status SPECIFIED. Consumers are authorized by explicit subscription contract. No contract is IMPLEMENTED.")
W (Join-Path $s 'entry-gate.md') "# بوابة دخول S01`n`nSRS/V5/AGENTS/S00 artifacts exist. RTM imports to 253 rows. S00 gate=PASS. OPEN-01..OPEN-09 inspected and remain OPEN. Ownership rules inspected. Git status failed with `not a git repository`; no worktree/branch/parallel Git operation was attempted. No prior contracts/schemas/tests/ADRs existed before S01 except S00 ADR register. This is a Git safety limitation, not a blocker for approved documentation/contracts."
W (Join-Path $s 'ticket.md') "# S01 Ticket`n`nArchitecture and contract baseline only. Owners: A0 documentation and A7 contract paths; QA independence is not available in this single session and is recorded as pending A6 review. No business logic/migrations/S02/S03 work."
W (Join-Path $s 'open-decisions-impact.md') "# أثر القرارات المفتوحة`n`n| OPEN | العقود المتأثرة | Mock/config placeholder | Blocks implementation? | Blocks pilot/commercial activation? |`n|---|---|---|---|---|`n| 01-02 | pricing/wallet/booking | نعم، بلا قيمة تجارية | لا للعقد | نعم |`n| 03-04 | microbus/booking/trips | نعم، state/event extensibility | الأثر النهائي فقط | نعم |`n| 05 | location/queue | fixture فقط | لا | ادعاء background GPS |`n| 06 | auth/wallet/location adapters | نعم | provider integration | نعم |`n| 07 | restricted-data contracts | أقل صلاحية فقط | retention activation | نعم |`n| 08 | compliance/investigation adapter | disabled boundary | real integration | نعم |`n| 09 | all performance assumptions | no numeric claim | load acceptance | pilot capacity |"
W (Join-Path $s 'test-cases.md') "# حالات اختبار S01`n`nCONTRACT-01 parse OpenAPI; CONTRACT-02 parse JSON schemas; CONTRACT-03 validate every operation owner/source/ID; CONTRACT-04 fixtures JSON and no secret markers; COMPAT-01 baseline has all operationIds; COMPAT-02 in-memory removal of operationId is detected; COMPAT-03 baseline remains unchanged; BOUNDARY-01 allowed public contract import is allowed; BOUNDARY-02 internal domain import is rejected by rule specification. Runtime DB/auth/payment/outbox tests: NOT_RUN pending implementation."
W (Join-Path $s 'handoff.md') "# S01 Handoff`n`n## S02`nCreate pnpm structure preserving `packages/contracts`; run `validate-s01.ps1` in CI; enforce dependency rules and ownership; use strict TypeScript/JSON formatting; never alter proposed contracts without compatibility check.`n`n## S03`nImplement logical schemas by owner, local transactions/outbox/idempotency records, unique constraints/row locks/version checks from transaction/concurrency docs. A7 owns migrations. No retention/provider/fee assumptions.`n`n## Frontends`nConsume v1 OpenAPI only, fixtures, ErrorEnvelope, correlation IDs and safe pagination; never backend internals."
